static const rc_icon_t s_icons[] = {
    { RC_ICON_W, RC_ICON_H, s_px_marquise },
    { RC_ICON_W, RC_ICON_H, s_px_eyrie },
    { RC_ICON_W, RC_ICON_H, s_px_woodland },
    { RC_ICON_W, RC_ICON_H, s_px_vagabond },
    { RC_ICON_W, RC_ICON_H, s_px_riverfolk },
    { RC_ICON_W, RC_ICON_H, s_px_cult },
    { RC_ICON_W, RC_ICON_H, s_px_duchy },
    { RC_ICON_W, RC_ICON_H, s_px_corvid },
    { RC_ICON_W, RC_ICON_H, s_px_hundreds },
    { RC_ICON_W, RC_ICON_H, s_px_keepers },
    { RC_ICON_W, RC_ICON_H, s_px_twilight },
    { RC_ICON_W, RC_ICON_H, s_px_knaves },
    { RC_ICON_W, RC_ICON_H, s_px_lilypad },
};
_Static_assert(sizeof s_icons / sizeof s_icons[0] == (size_t)RC_FACTION_COUNT,
               "one icon per rc_faction_id_t, in enum order");

static const rc_icon_t s_none = { RC_ICON_W, RC_ICON_H, NULL };

const rc_icon_t *rc_icon_get(uint8_t faction_id) {
    if (faction_id < RC_FACTION_COUNT) {
        return &s_icons[faction_id];
    }
    return &s_none;
}
